41	static constexpr const int DEFAUT_MODEL_ID = 2;
42	
43	struct CrossCoreSyncPoint {
44	  int scope;        // 0: cube, 1: vec
45	  int order;        // execute order
46	  int sync_flag_id; // cross core sync flag id
47	  bool is_write;    // whether write to workspace or not
48	  std::string workspace_name;
49	  std::string pipe; // MTE2, MTE3 or FIX
50	  const EvaluateNode *node;
51	  std::optional<const ForNode *> target_for_node = std::nullopt;
52	  // the ForNode to which the sync stmt will be attached. If not specified, will
53	  // be attached to the EvaluateNode.
54	  std::vector<const ForNode *> parent_for_nodes;
55	  // the ForNode list (from outer to inner) before reaching the EvaluateNode
56	
57	  // Cross interval support
58	  int cross_interval = 1;
59	  const ForNode *stage_loop = nullptr;
60	
61	  std::string ToString() const {
62	    std::ostringstream oss;
63	    oss << "CrossCoreSyncPoint(";
64	    oss << "scope=" << scope;
65	    oss << ", order=" << order;
66	    oss << ", sync_flag_id=" << sync_flag_id;
67	    oss << ", is_write=" << is_write;
68	    oss << ", workspace_name=" << workspace_name;
69	    oss << ", pipe=" << pipe;
70	    if (target_for_node.has_value()) {
71	      oss << ", target_for_node="
72	          << target_for_node.value()->loop_var->name_hint;
73	    } else {
74	      oss << ", target_for_node=None";
75	    }
76	    oss << ", parent_for_nodes.size()=" << parent_for_nodes.size();
77	    oss << ", cross_interval=" << cross_interval;
78	    oss << ")";
79	    return oss.str();
80	  }
81	};
