83	class CrossCoreSyncCollector : public StmtVisitor {
84	public:
85	  CrossCoreSyncCollector(std::vector<CrossCoreSyncPoint> &sync_points,
86	                         const bool is_aiv)
87	      : sync_points_(sync_points), is_aiv_(is_aiv) {}
88	
89	  const std::vector<CrossCoreSyncPoint> &GetSyncPoints() const {
90	    return sync_points_;
91	  }
92	
93	  void VisitStmt_(const EvaluateNode *op) override {
94	    if (auto call_node = op->value.as<CallNode>()) {
95	      order_++;
96	
97	      if (!call_node->op.same_as(builtin::call_extern())) {
98	        return;
99	      }
100	
101	      std::string func_name = call_node->args[0].as<StringImmNode>()->value;
102	
103	      if (auto cfg_info = GetGMCopyCfgInfo(func_name)) {
104	        bool is_write = cfg_info->first;
105	        std::string pipe = cfg_info->second;
106	
107	        if (auto workspace_name_opt = FetchWorkspaceName(call_node)) {
108	          CrossCoreSyncPoint sp;
109	          sp.scope = is_aiv_ ? 1 : 0;
110	          sp.order = order_;
111	          sp.sync_flag_id = sync_flag_id_++;
112	          sp.is_write = is_write;
113	          sp.workspace_name = workspace_name_opt.value();
114	          sp.pipe = pipe;
115	          sp.node = op;
116	          sp.target_for_node = std::nullopt;
117	          sp.parent_for_nodes = current_loops_;
118	          sp.cross_interval = GetCrossInterval();
119	          sp.stage_loop = current_stage_loop_;
120	          sync_points_.push_back(sp);
121	        }
122	      }
123	    }
124	  }
125	
126	  void VisitStmt_(const ForNode *op) override {
127	    bool is_stage_loop = op->annotations.Get("stage_loop").defined();
128	
129	    if (is_stage_loop) {
130	      current_stage_loop_ = op;
131	    }
132	
133	    current_loops_.push_back(op);
134	    StmtVisitor::VisitStmt_(op);
135	    current_loops_.pop_back();
136	
137	    if (is_stage_loop) {
138	      current_stage_loop_ = nullptr;
139	    }
140	  }
141	
142	  int GetCrossInterval() const {
143	    if (current_stage_loop_) {
144	      auto interval_anno =
145	          current_stage_loop_->annotations.Get("tl_cross_interval");
146	      if (interval_anno.defined()) {
147	        return interval_anno.as<IntImmNode>()->value;
148	      }
149	    }
150	    return 1;
151	  }
152	
153	private:
154	  std::vector<CrossCoreSyncPoint> &sync_points_;
155	  const bool is_aiv_{false};
156	  int order_{0};
157	  int sync_flag_id_{0};
158	  std::vector<const ForNode *> current_loops_;
159	  const ForNode *current_stage_loop_ = nullptr;
160	
161	  /**
162	   * The configuration info table
163	   *
164	   * key: GM related function name
165	   * value: pair<isWrite, pipe>
166	   */
167	  const std::unordered_map<std::string, std::pair<bool, std::string>>
168	      GM_COPY_CFG_INFOS = {
169	          {"copy_gm_to_l1", {false, "MTE2"}},
170	          {"copy_l0c_to_gm", {true, "FIX"}},
171	          {"copy_gm_to_ub", {false, "MTE2"}},
172	          {"copy_ub_to_gm", {true, "MTE3"}},
173	          {"atomic_add_ub_to_gm", {true, "MTE3"}},
174	          {"atomic_add_l0c_to_gm", {true, "FIX"}},
175	      };
176	
177	  std::optional<std::pair<bool, std::string>>
178	  GetGMCopyCfgInfo(const std::string &func_name) {
179	    for (const auto &item : GM_COPY_CFG_INFOS) {
180	      if (func_name.find(item.first) != std::string::npos) {
181	        return item.second;
182	      }
183	    }
184	    return std::nullopt;
185	  }
186	
187	  /**
188	   * Fetch workspace from CallNode.
189	   */
190	  std::optional<std::string> FetchWorkspaceName(const CallNode *call_node) {
191	    auto args = call_node->args;
192	    for (int i = 1; i < args.size(); ++i) {
193	      if (auto inner_call_node = args[i].as<CallNode>()) {
194	        std::string buf_name =
195	            Downcast<Var>(inner_call_node->args[1])->name_hint;
196	        if (buf_name.find("workspace") != std::string::npos) {
197	          return buf_name;
198	        }
199	      }
200	    }
201	    return std::nullopt;
202	  }
203	};
