205	class CrossCoreSyncInserter : public StmtMutator {
206	public:
207	  CrossCoreSyncInserter(std::vector<CrossCoreSyncPoint> &sync_points)
208	      : sync_points_(sync_points) {}
209	
210	  Stmt VisitStmt_(const EvaluateNode *op) override {
211	    if (auto call_node = op->value.as<CallNode>()) {
212	      cur_order_++;
213	      for (const auto &sp : sync_points_) {
214	        // Match sync point
215	        if (sp.order != cur_order_) {
216	          continue;
217	        }
218	
219	        // ForNode target, skip here; will be handled in ForNode visitor
220	        if (sp.target_for_node.has_value()) {
221	          continue;
222	        }
223	
224	        // Insert wait/set flag
225	        return AttachSyncStmt(sp, GetRef<Stmt>(op));
226	      }
227	    }
228	    return GetRef<Stmt>(op);
229	  }
230	
231	  Stmt VisitStmt_(const ForNode *op) override {
232	    Stmt new_body = this->VisitStmt(op->body);
233	    Stmt new_stmt = For(op->loop_var, op->min, op->extent, op->kind, new_body,
234	                        op->thread_binding, op->annotations);
235	
236	    for (const auto &sp : sync_points_) {
237	      // Check ForNode
238	      if (!sp.target_for_node) {
239	        continue;
240	      }
241	
242	      // Check ForNode match
243	      if (!op->body.same_as(sp.target_for_node.value()->body)) {
244	        continue;
245	      }
246	
247	      // Insert sync stmt for the For loop
248	      new_stmt = AttachSyncStmt(sp, new_stmt);
249	    }
250	
251	    return new_stmt;
252	  }
253	
254	private:
255	  int cur_order_{0};
256	  const std::vector<CrossCoreSyncPoint> &sync_points_;
257	
258	  /**
259	   * SetFlag After Write, WaitFlag Before Read.
260	   * Note: Only sync_stmt is conditional, op_stmt (data copy) always executes.
261	   */
262	  Stmt AttachSyncStmt(const CrossCoreSyncPoint &sp, const Stmt &op_stmt) {
263	    Stmt sync_stmt;
264	    if (sp.is_write) {
265	      sync_stmt = GenAutoCrossCoreSetFlagStmt(sp);
266	    } else {
267	      sync_stmt = GenAutoCrossCoreWaitFlagStmt(sp);
268	    }
269	
270	    if (sp.cross_interval > 1 && sp.stage_loop != nullptr) {
271	      PrimExpr condition = GenSyncCondition(sp);
272	      // op_stmt always executes, sync_stmt is conditional
273	      if (sp.is_write) {
274	        // writer: op_stmt first, then conditional sync
275	        return SeqStmt(
276	            {op_stmt, IfThenElse(condition, sync_stmt, Evaluate(0))});
277	      } else {
278	        // reader: conditional sync first, then op_stmt
279	        return SeqStmt(
280	            {IfThenElse(condition, sync_stmt, Evaluate(0)), op_stmt});
281	      }
282	    }
283	
284	    if (sp.is_write) {
285	      return SeqStmt({op_stmt, sync_stmt});
286	    } else {
287	      return SeqStmt({sync_stmt, op_stmt});
288	    }
289	  }
290	
291	  /**
292	   * Generate sync condition based on cross_interval.
293	   * Writer (set): (stage_var % cross_interval == cross_interval - 1) ||
294	   * is_last_iteration Reader (wait): stage_var % cross_interval == 0
295	   */
296	  PrimExpr GenSyncCondition(const CrossCoreSyncPoint &sp) {
297	    const ForNode *stage_loop = sp.stage_loop;
298	    if (stage_loop == nullptr) {
299	      return make_const(DataType::Bool(), true);
300	    }
301	    PrimExpr stage_var = stage_loop->loop_var;
302	    PrimExpr stage_extent = stage_loop->extent;
303	    int cross_interval = sp.cross_interval;
304	    auto int32 = DataType::Int(32);
305	
306	    if (sp.is_write) {
307	      PrimExpr mod_cond = EQ(Mod(stage_var, make_const(int32, cross_interval)),
308	                             make_const(int32, cross_interval - 1));
309	      PrimExpr last_iter_cond =
310	          EQ(stage_var, Sub(stage_extent, make_const(int32, 1)));
311	      return tir::Or(mod_cond, last_iter_cond);
312	    } else {
313	      return EQ(Mod(stage_var, make_const(int32, cross_interval)),
314	                make_const(int32, 0));
315	    }
316	  }
317	
318	  /**
319	   * Generate CrossCoreSetFlag
320	   */
321	  Stmt GenAutoCrossCoreSetFlagStmt(const CrossCoreSyncPoint &sp) {
322	    return Evaluate(Call(DataType::Handle(),
323	                         Op::Get("tl.ascend_auto_set_cross_flag"),
324	                         {
325	                             Integer(DEFAUT_MODEL_ID),
326	                             StringImm(sp.pipe),
327	                             Integer(sp.sync_flag_id),
328	                         }));
329	  }
330	
331	  /**
332	   * Generate CrossCoreWaitFlag
333	   */
334	  Stmt GenAutoCrossCoreWaitFlagStmt(const CrossCoreSyncPoint &sp) {
335	    return Evaluate(Call(DataType::Handle(),
336	                         Op::Get("tl.ascend_auto_wait_cross_flag"),
337	                         {
338	                             Integer(sp.sync_flag_id),
339	                             StringImm(sp.pipe),
340	                         }));
341	  }
342	};
