344	class AutoInsertCrossCoreSync {
345	public:
346	  static void AutoInsert(Stmt &cube_code, Stmt &vec_code) {
347	    // Collect sync points
348	    std::vector<CrossCoreSyncPoint> cube_sync_points;
349	    std::vector<CrossCoreSyncPoint> vec_sync_points;
350	
351	    CrossCoreSyncCollector cube_collector(cube_sync_points, false);
352	    CrossCoreSyncCollector vec_collector(vec_sync_points, true);
353	
354	    cube_collector(cube_code);
355	    vec_collector(vec_code);
356	
357	    // Map to group sync points by workspace_name
358	    std::map<std::string, std::vector<CrossCoreSyncPoint *>> cube_ws_map;
359	    std::map<std::string, std::vector<CrossCoreSyncPoint *>> vec_ws_map;
360	
361	    for (auto &sp : cube_sync_points) {
362	      cube_ws_map[sp.workspace_name].push_back(&sp);
363	    }
364	    for (auto &sp : vec_sync_points) {
365	      vec_ws_map[sp.workspace_name].push_back(&sp);
366	    }
367	
368	    int global_sync_flag_id = 0;
369	
370	    for (auto &[ws, cube_sps] : cube_ws_map) {
371	      auto &vec_sps = vec_ws_map[ws];
372	
373	      // Check sync points consistency per workspace
374	      if (cube_sps.size() != vec_sps.size()) {
375	        LOG(FATAL) << "Mismatch in sync points between cube and vec for "
376	                      "workspace "
377	                   << ws << ": " << "cube has " << cube_sps.size() << ", "
378	                   << "vec has " << vec_sps.size();
379	      }
380	
381	      for (size_t i = 0; i < cube_sps.size(); ++i) {
382	        auto *cube_sp = cube_sps[i];
383	        auto *vec_sp = vec_sps[i];
384	
385	        if (cube_sp->is_write == vec_sp->is_write) {
386	          LOG(FATAL) << "Inconsistent read/write operations for workspace "
387	                     << ws << " at sync point " << i
388	                     << ": cube is_write=" << cube_sp->is_write << ", "
389	                     << "vec is_write=" << vec_sp->is_write;
390	        }
391	
392	        // Assign a common sync_flag_id for matched pair
393	        cube_sp->sync_flag_id = global_sync_flag_id;
394	        vec_sp->sync_flag_id = global_sync_flag_id;
395	        global_sync_flag_id++;
396	
397	        // find target_for_node using iterative depth search
398	        FindTargetLoopDepth(*cube_sp, *vec_sp);
399	      }
400	    }
401	
402	    // Insert sync statements
403	    CrossCoreSyncInserter cube_sync_inserter(cube_sync_points);
404	    CrossCoreSyncInserter vec_sync_inserter(vec_sync_points);
405	
406	    cube_code = cube_sync_inserter(cube_code);
407	    vec_code = vec_sync_inserter(vec_code);
408	  }
409	
410	private:
411	  // return loop iter times as const int64_t* or nullptr
412	  static const int64_t *IterTimesAsConst(const ForNode *for_node) {
413	    return as_const_int(for_node->extent);
414	  }
415	
416	  static int64_t GetLoopIterTimes(const ForNode *for_node) {
417	    const int64_t *extent_ptr = IterTimesAsConst(for_node);
418	    ICHECK(extent_ptr) << "AutoInsertCrossCoreSync::GetLoopIterTimes only "
419	                          "works with constant loop sizes, but got "
420	                       << for_node->extent;
421	    return *extent_ptr;
422	  }
423	
424	  // get loop iter times but skip loop whose id in skip_loop_ids
425	  static int64_t GetLoopIterTimesWithSkip(
426	      const ForNode *for_node,
427	      const std::unordered_set<std::string> &skip_loop_ids) {
428	    if (skip_loop_ids.find(for_node->loop_var->name_hint) !=
429	        skip_loop_ids.end()) {
430	      return 1; // skip this loop by treating it as 1 iter
431	    }
432	    return GetLoopIterTimes(for_node);
433	  }
434	
435	  // check if same depth & same name in both parent_for_nodes
436	  static bool
437	  IsSharedLoop(int loop_index,
438	               const std::vector<const ForNode *> &cube_parent_for_nodes,
439	               const std::vector<const ForNode *> &vec_parent_for_nodes) {
440	    if (loop_index >= cube_parent_for_nodes.size() ||
441	        loop_index >= vec_parent_for_nodes.size()) {
442	      return false;
443	    }
444	    return cube_parent_for_nodes[loop_index]->loop_var->name_hint ==
445	           vec_parent_for_nodes[loop_index]->loop_var->name_hint;
446	  }
447	
448	  // collect ids of shared loops with non-constant iter times
449	  static std::unordered_set<std::string> CollectNonConstSharedLoopIds(
450	      const std::vector<const ForNode *> &cube_parent_for_nodes,
451	      const std::vector<const ForNode *> &vec_parent_for_nodes) {
452	    std::unordered_set<std::string> non_const_shared_loop_ids;
453	    int min_size =
454	        std::min(cube_parent_for_nodes.size(), vec_parent_for_nodes.size());
455	    for (int i = 0; i < min_size; ++i) {
456	      const auto *cube_loop = cube_parent_for_nodes[i];
457	      // is non-const loop and is shared by cube and vec
458	      if (IterTimesAsConst(cube_loop) == nullptr &&
459	          IsSharedLoop(i, cube_parent_for_nodes, vec_parent_for_nodes)) {
460	        non_const_shared_loop_ids.insert(cube_loop->loop_var->name_hint);
461	      }
462	    }
463	    return non_const_shared_loop_ids;
464	  }
465	
466	  // find target ForNodes to attach sync stmts
467	  static void FindTargetLoopDepth(CrossCoreSyncPoint &cube_sp,
468	                                  CrossCoreSyncPoint &vec_sp) {
469	    if (cube_sp.parent_for_nodes.empty() && vec_sp.parent_for_nodes.empty()) {
470	      return; // sync point pairs aren't in any loop
471	    }
472	
473	    auto skip_loop_ids = CollectNonConstSharedLoopIds(cube_sp.parent_for_nodes,
474	                                                      vec_sp.parent_for_nodes);
475	
476	    if (!skip_loop_ids.empty()) {
477	      // log skip_loop_ids
478	      std::string loop_ids;
479	      for (const auto &_id : skip_loop_ids) {
480	        if (!loop_ids.empty())
481	          loop_ids += ", ";
482	        loop_ids += _id;
483	      }
484	      DLOG(DEBUG)
485	          << "Found " << skip_loop_ids.size()
486	          << " shared loop(s) with non-constant iter times: [" << loop_ids
487	          << "]. These loop(s) won't be counted for total loop times of \""
488	          << cube_sp.workspace_name << "\"'s sync points.\n";
489	    }
490	
491	    // total loop times of sync points
492	    int64_t cube_loop_times = 1;
493	    int64_t vec_loop_times = 1;
494	    // current index of CrossCoreSyncPoint.parent_for_nodes
495	    int cube_loop_idx = 0;
496	    int vec_loop_idx = 0;
497	    // current max loop depth when cube_loop_times == vec_loop_times
498	    int cube_max_pair_depth = 0;
499	    int vec_max_pair_depth = 0;
500	    // handle corner case: vec has loops with 1 iter and can't catch up cube
501	    // loop times
502	    int64_t last_pair_loop_times = 1;
503	
504	    // iterate through both cube_sp.parent_for_nodes and vec_sp.parent_for_nodes
505	    // once
506	    while (cube_loop_idx < cube_sp.parent_for_nodes.size() ||
507	           vec_loop_idx < vec_sp.parent_for_nodes.size()) {
508	      bool cube_idx_updated = false;
509	      while (
510	          cube_loop_idx < cube_sp.parent_for_nodes.size() &&
511	          (cube_loop_times <= vec_loop_times ||
512	           GetLoopIterTimesWithSkip(cube_sp.parent_for_nodes.at(cube_loop_idx),
513	                                    skip_loop_ids) == 1)) {
514	        if (cube_loop_times == vec_loop_times) {
515	          cube_max_pair_depth = cube_loop_idx;
516	          vec_max_pair_depth = vec_loop_idx;
517	          last_pair_loop_times = cube_loop_times;
518	        }
519	
520	        const ForNode *cube_loop = cube_sp.parent_for_nodes.at(cube_loop_idx);
521	        cube_loop_times *= GetLoopIterTimesWithSkip(cube_loop, skip_loop_ids);
522	        cube_loop_idx++;
523	        cube_idx_updated = true;
524	      }
525	
526	      if (cube_loop_times < vec_loop_times) {
527	        LOG(WARNING) << "Cube loop times (= " << cube_loop_times
528	                     << " ) is not enough to catch up vec loop times (= "
529	                     << vec_loop_times << " )\n"
530	                     << "Cube Sync Point:\n"
531	                     << cube_sp.ToString() << "\n"
532	                     << "Vec Sync Point:\n"
533	                     << vec_sp.ToString() << "\n";
534	      }
535	
536	      bool vec_idx_updated = false;
537	      while (vec_loop_idx < vec_sp.parent_for_nodes.size() &&
538	             (vec_loop_times <= cube_loop_times ||
539	              GetLoopIterTimesWithSkip(vec_sp.parent_for_nodes.at(vec_loop_idx),
540	                                       skip_loop_ids) == 1)) {
541	        if (cube_loop_times == vec_loop_times) {
542	          cube_max_pair_depth = cube_loop_idx;
543	          vec_max_pair_depth = vec_loop_idx;
544	          last_pair_loop_times = cube_loop_times;
545	        }
546	
547	        const ForNode *vec_loop = vec_sp.parent_for_nodes.at(vec_loop_idx);
548	        vec_loop_times *= GetLoopIterTimesWithSkip(vec_loop, skip_loop_ids);
549	        vec_loop_idx++;
550	        vec_idx_updated = true;
551	
552	        if (vec_loop_times == last_pair_loop_times) {
553	          // cube_loop_times steps beyond last_pair_loop_times && vec_loop_times
554	          // doesn't increase ( *= 1 )
555	          vec_max_pair_depth = vec_loop_idx;
556	        }
557	      }
558	
559	      if (vec_loop_times < cube_loop_times) {
560	        LOG(WARNING) << "Vec loop times (= " << vec_loop_times
561	                     << " ) is not enough to catch up cube loop times (= "
562	                     << cube_loop_times << " )\n"
563	                     << "Vec Sync Point:\n"
564	                     << vec_sp.ToString() << "\n"
565	                     << "Cube Sync Point:\n"
566	                     << cube_sp.ToString() << "\n";
567	      }
568	
569	      if (!(cube_idx_updated || vec_idx_updated)) {
570	        break;
571	      }
572	    }
573	
574	    if (cube_loop_times == vec_loop_times) {
575	      // in case the loop instantly ends after vec_loop_idx step to next loop
576	      cube_max_pair_depth = cube_loop_idx;
577	      vec_max_pair_depth = vec_loop_idx;
578	    }
579	
580	    // target_for_node is the for loop at max_pair_depth (if it has a for loop
581	    // at that depth)
582	    if (0 <= cube_max_pair_depth &&
583	        cube_max_pair_depth < cube_sp.parent_for_nodes.size()) {
584	      cube_sp.target_for_node =
585	          cube_sp.parent_for_nodes.at(cube_max_pair_depth);
586	    }
587	
588	    if (0 <= vec_max_pair_depth &&
589	        vec_max_pair_depth < vec_sp.parent_for_nodes.size()) {
590	      vec_sp.target_for_node = vec_sp.parent_for_nodes.at(vec_max_pair_depth);
591	    }
592	
593	    // otherwise, target_for_node remains nullopt
594	  }
595	};
596	
597	class CVCombineEmitter : public StmtMutator {
598	public:
599	  CVCombineEmitter(bool is_aiv, Map<Var, String> &location)
600	      : is_aiv_(is_aiv), location_map_(location) {}
601	
602	  std::string
603	  isSubstringInMap(const std::unordered_map<std::string, std::string> &m,
604	                   const std::string &target) {
605	    if (target.empty()) {
606	      return std::string("");
607	    }
608	    size_t target_len = target.length();
609	    for (const auto &pair : m) {
610	      const std::string &key = pair.first;
611	      if (target.find(key) != std::string::npos) {
612	        return pair.second;
613	      }
614	    }
615	    return std::string("");
616	  }
617	
618	  int32_t checkBufferScope(const Var &var) {
619	    int32_t check_ternaty = -1;
620	    if (is_aiv_) {
621	      if (location_map_.find(var) != location_map_.end()) {
622	        if (callnodeMapPos_[location_map_[var]] == "vec") {
623	          check_ternaty = 1;
624	        } else if (callnodeMapPos_[location_map_[var]] == "cube") {
625	          check_ternaty = 0;
626	        } else {
627	          check_ternaty = -1;
628	        }
629	      }
630	    } else {
631	      if (location_map_.find(var) != location_map_.end()) {
632	        if (callnodeMapPos_[location_map_[var]] == "cube") {
633	          check_ternaty = 1;
634	        } else if (callnodeMapPos_[location_map_[var]] == "vec") {
635	          check_ternaty = 0;
636	        } else {
637	          check_ternaty = -1;
638	        }
639	      }
640	    }
641	    return check_ternaty;
642	  }
643	
644	  // some scene need
645	  // Stmt VisitStmt_(const ForNode *op) final {
646	  //     current_proccess_switch_ = false; // turn off
647	  //     return StmtMutator::VisitStmt_(op);
648	  // }
649	  Stmt VisitStmt_(const ForNode *op) final {
650	    Stmt new_stmt = StmtMutator::VisitStmt_(op);
651	
652	    const ForNode *new_for = new_stmt.as<ForNode>();
653	    if (!new_for) {
654	      return new_stmt;
655	    }
656	
657	    Stmt new_body = new_for->body;
658	    // Recursively check if the body is effectively empty
659	    // (e.g., BlockRealize with only alloc_buffers and Evaluate(0))
660	    if (IsEmptyBody(new_body)) {
661	      return Evaluate(0);
662	    }
663	
664	    return new_stmt;
665	  }
666	
667	  bool IsEmptyBody(const Stmt &stmt) {
668	    if (const auto *eval = stmt.as<EvaluateNode>()) {
669	      if (const auto *int_imm = eval->value.as<IntImmNode>()) {
670	        return int_imm->value == 0;
671	      }
672	    }
673	    if (const auto *alloc = stmt.as<AllocateNode>()) {
674	      return IsEmptyBody(alloc->body);
675	    }
676	    if (const auto *realize = stmt.as<BlockRealizeNode>()) {
677	      // Check if block only has allocations and no actual statements
678	      return IsEmptyBody(realize->block->body);
679	    }
680	    if (const auto *block = stmt.as<BlockNode>()) {
681	      // Block may have alloc_buffers, but we only care about the body
682	      return IsEmptyBody(block->body);
683	    }
684	    if (const auto *if_then_else = stmt.as<IfThenElseNode>()) {
685	      bool then_empty = IsEmptyBody(if_then_else->then_case);
686	      bool else_empty = if_then_else->else_case.defined()
687	                            ? IsEmptyBody(if_then_else->else_case.value())
688	                            : true;
689	      return then_empty && else_empty;
690	    }
691	    if (const auto *seq = stmt.as<SeqStmtNode>()) {
692	      for (const auto &s : seq->seq) {
693	        if (!IsEmptyBody(s)) {
694	          return false;
695	        }
696	      }
697	      return true;
698	    }
699	    return false;
700	  }
701	
702	  Stmt VisitStmt_(const EvaluateNode *op) final {
703	    auto call_node_ = op->value.as<CallNode>();
704	    if (!call_node_) {
705	      return StmtMutator::VisitStmt_(op);
706	    }
707	    std::string api_name = "";
708	    if (call_node_) {
709	      if (const auto *str_imm = call_node_->args[0].as<StringImmNode>()) {
710	        api_name = str_imm->value;
711	      }
712	      if (const auto *op_node = call_node_->op.as<OpNode>();
713	          op_node && IsRetainedInBothScopes(op_node->name)) {
714	        return GetRef<Stmt>(op);
715	      }
716	    }
717	    auto found = isSubstringInMap(callnodeMapPos_, api_name);
718	    // judgement 1
719	    if (is_aiv_) {
720	      if (found == "vec") {
721	        current_proccess_switch_ = true; // turn on
722	        return StmtMutator::VisitStmt_(op);
723	      } else if (found == "cube") {
724	        current_proccess_switch_ = false; // turn off
725	      }
726	    } else {
727	      if (found == "cube") {
728	        current_proccess_switch_ = true; // turn on
729	        return StmtMutator::VisitStmt_(op);
730	      } else if (found == "vec") {
731	        current_proccess_switch_ = false; // turn off
732	      }
733	    }
734	    // judgement 2
735	    int32_t judge2 = -1;
736	    for (int i = 0; i < call_node_->args.size(); i++) {
737	      if (auto inter_node = call_node_->args[i].as<CallNode>()) {
738	        auto buf_name = Downcast<Var>(inter_node->args[1]);
739	        judge2 = checkBufferScope(buf_name);
740	        if (judge2 != -1) {
741	          break;
742	        }
743	      }
744	    }
745	    if (judge2 == 1) {
746	      current_proccess_switch_ = true; // turn on
747	      return StmtMutator::VisitStmt_(op);
748	    } else if (judge2 == -1 && current_proccess_switch_) {
749	      return StmtMutator::VisitStmt_(op);
750	    }
751	    current_proccess_switch_ = false; // turn off
752	    return Evaluate(0);
753	  }
754	
755	  Stmt VisitStmt_(const BufferStoreNode *op) final {
756	    auto buf_scope = op->buffer.scope();
757	    if (is_aiv_) {
758	      if (buf_scope == "shared.ub") {
759	        return StmtMutator::VisitStmt_(op);
760	      } else {
761	        return Evaluate(0);
762	      }
763	    } else {
764	      if (buf_scope == "shared.ub") {
765	        return Evaluate(0);
766	      } else {
767	        return StmtMutator::VisitStmt_(op);
768	      }
769	    }
770	  }
771	
772	  bool IsRetainedInBothScopes(const std::string &api_name) {
773	    // APIs that do not belong to cube or vec scope,
774	    // and should be retained in both generated code paths (e.g. printf).
775	    static const std::vector<std::string> kBothScopesApis = {
776	        "tl.ascend_printf",
777	    };
778	    for (const auto &target_api : kBothScopesApis) {
779	      if (api_name.find(target_api) != std::string::npos) {
780	        return true;
781	      }
782	    }
783	    return false;
784	  }
785	
786	private:
787	  const bool is_aiv_;
788	  bool current_proccess_switch_ = false;
789	  Map<Var, String> &location_map_;
790	  std::unordered_map<std::string, std::string> callnodeMapPos_ = {
791	      {"copy_gm_to_l1", "cube"},
792	      {"gemm_v0", "cube"},
793	      {"copy_l1_to_l0a", "cube"},
794	      {"copy_l1_to_l0b", "cube"},
795	      {"copy_l0c_to_gm", "cube"},
796	      {"copy_gm_to_ub", "vec"},
797	      {"copy_ub_to_gm", "vec"},
798	      {"atomic_add_ub_to_gm", "vec"},
799	      {"atomic_add_l0c_to_gm", "cube"},
800	      {"copy_ub_to_ub", "vec"},
801	      {"wmma.matrix_a", "cube"},
802	      {"wmma.matrix_b", "cube"},
803	      {"wmma.accumulator", "cube"},
804	      {"shared.l1", "cube"},
805	      {"shared.ub", "vec"},
806	      {"copy_ub_to_ub_Nz", "vec"},
807	      {"copy_ub_to_pipe", "vec"},
808	      {"copy_pipe_to_l1", "cube"},
809	      {"copy_l0c_to_pipe", "cube"},
810	      {"copy_pipe_to_ub", "vec"},
811	      {"copy_pipe_to_ub_V", "vec"},
812	      {"free_pipe_C", "cube"},
813	      {"free_pipe_V", "vec"},
814	  };
815	};
816	
817	class CombineCV : public arith::IRMutatorWithAnalyzer {
818	public:
819	  static PrimFunc Substitute(PrimFunc f, PassContext ctx) {
820	    arith::Analyzer analyzer;
821	    CombineCV substituter(&analyzer);
822	    PrimFuncNode *fptr = f.CopyOnWrite();
823	    tir::PostOrderVisit(f->body, [&](const ObjectRef &obj) {
824	      if (const auto *realize = obj.as<tir::BlockRealizeNode>()) {
825	        for (auto buf : realize->block->alloc_buffers) {
826	          String scope = GetPtrStorageScope(buf->data);
827	          substituter.location_map_.Set(buf->data, scope);
828	        }
829	      }
830	    });
831	
832	    bool ascend_auto_combine =
833	        ctx->GetConfig<Bool>(ascendAutoCombine, Bool(false)).value();
834	    if (!ascend_auto_combine) {
835	      return f;
836	    }
837	
838	    substituter.is_auto_cross_core_sync_ =
839	        ctx->GetConfig<Bool>(ascendAutoCrossCoreSync, Bool(false)).value();
840	
841	    fptr->body = substituter.VisitStmt(f->body);
842	    return f;
843	  }
844	
845	private:
846	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
847	
848	  Stmt VisitStmt_(const BlockRealizeNode *op) override {
849	    if (op->block->name_hint == "tilelang_root") {
850	      Block block = op->block;
851	
852	      CVCombineEmitter cubeStmt(false, location_map_);
853	      CVCombineEmitter vecStmt(true, location_map_);
854	
855	      Stmt cube_code = cubeStmt(block->body);
856	      Stmt vec_code = vecStmt(block->body);
857	
858	      if (is_auto_cross_core_sync_) {
859	        AutoInsertCrossCoreSync::AutoInsert(cube_code, vec_code);
860	      }
861	
862	      Stmt cube_body = AttrStmt(make_zero(DataType::Int(32)), "resource_scope",
863	                                0, cube_code);
864	      Stmt vec_body =
865	          AttrStmt(make_zero(DataType::Int(32)), "resource_scope", 1, vec_code);
866	      Stmt combine_body = SeqStmt({cube_body, vec_body});
867	      block.CopyOnWrite()->body = combine_body;
868	      auto blockRealize = GetRef<BlockRealize>(op);
869	      blockRealize.CopyOnWrite()->block = block;
870	      return blockRealize;
871	    }
872	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
873	  }
874	
875	  Stmt VisitStmt_(const AllocateNode *op) override {
876	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
877	  }
878	
879	  Map<Var, String> location_map_;
880	  bool is_auto_cross_core_sync_{false};
881	};
882	
883	tvm::transform::Pass CombineCV() {
884	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
885	    auto new_func = CombineCV::Substitute(std::move(f), ctx);
886	    return new_func;
887	  };
888	  return CreatePrimFuncPass(pass_func, 0, "tl.CombineCV", {});
889	}
890	
891	// regist host path
892	TVM_REGISTER_GLOBAL("tl.transform.CombineCV").set_body_typed(CombineCV);
893	
894	} // namespace tl
895	} // namespace tvm
